Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(LedgerAllocationRuleSource, LedgerAllocationRuleSource_SourceCriteria), FormControlEventType::Lookup)]
public static void LedgerAllocationRuleSource_SourceCriteria_OnLookup(FormControl sender, FormControlEventArgs e)
{
    LedgerAllocationRuleSource          ruleSource = sender.formRun().dataSource(formDataSourceStr(LedgerAllocationRuleSource,LedgerAllocationRuleSource)).cursor();
    FormControlCancelableSuperEventArgs cancelableArgs = e as FormControlCancelableSuperEventArgs;

    if (ruleSource.FieldSetting == LedgerAllocationAccountDimension::SumAccount)
    {
        LedgerAllocationRuleSource::lookupSumMainAccounts(sender);

        cancelableArgs.CancelSuperCall();
    }
}
